export const upgradeWebSocket: UpgradeWebSocket<WebSocket, Deno.UpgradeWebSocketOptions> =
  defineWebSocketHelper(async (c, events, options) => {
    if (c.req.header('upgrade') !== 'websocket') { return }
    const subprotocol = c.req.header('sec-websocket-protocol')?.split(',')[0]?.trim()
    const { response, socket } = Deno.upgradeWebSocket(c.req.raw, {
      ...(subprotocol ? { protocol: subprotocol } : {}),
      ...options,
    })
    socket.onopen = (evt) => events.onOpen?.(evt, wsContext)
    socket.onmessage = (evt) => events.onMessage?.(evt, wsContext)
    return response
  })

export const handle = <E extends Env = Env, S extends Schema = {}, BasePath extends string = '/'>(
  app: Hono<E, S, BasePath>,
  { isContentTypeBinary }: HandleOptions = { isContentTypeBinary: undefined }
) => {
  return async (event, lambdaContext?) => {
    const processor = getProcessor(event)
    const req = processor.createRequest(event)
    const requestContext = getRequestContext(event)
    const res = await app.fetch(req, { event, requestContext, lambdaContext })
    return processor.createResult(event, res, { isContentTypeBinary })
  }
}

