  addEventListener('fetch', handle(app, options))
}

export const streamHandle = <E extends Env = Env, S extends Schema = {}, BasePath extends string = '/' >(
  app: Hono<E, S, BasePath>
): Handler => {
  // @ts-expect-error awslambda is not a standard API
  return awslambda.streamifyResponse(
    async (event, responseStream, context) => {
      const processor = getProcessor(event)
      const req = processor.createRequest(event)
      const res = await app.fetch(req, { event, requestContext: getRequestContext(event), context })
      // @ts-expect-error awslambda is not a standard API
      responseStream = awslambda.HttpResponseStream.from(responseStream, httpResponseMetadata)
      if (res.body) { await streamToNodeStream(res.body.getReader(), responseStream) }
    }
  )
}

